UPDATE "ChecksheetMaster" cm
SET "UnitApplicationId" = mua."Id"
FROM "MUnitApplication" mua
JOIN "MSector" ms ON mua."SectorId" = ms."Id"
WHERE cm."Sector" = ms."Name"
AND cm."UnitApplication" = mua."Name";
